import React from 'react';
import { 
  Container, 
  Typography, 
  Paper, 
  Grid, 
  Box, 
  List, 
  ListItem, 
  ListItemIcon, 
  ListItemText,
  useTheme
} from '@mui/material';
import { 
  Computer, 
  Speed, 
  Security, 
  CloudQueue 
} from '@mui/icons-material';

const Home = () => {
  const theme = useTheme();

  return (
    <Box sx={{ 
      minHeight: '100vh',
      backgroundImage: 'url("/fondo.jpg")',
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundRepeat: 'no-repeat',
      backgroundAttachment: 'fixed',
      position: 'relative',
      py: 0,
      '&::before': {
        content: '""',
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(45, 90, 140, 0.7)',
        zIndex: 1
      }
    }}>
      {/* Contenedor relativo para todo el contenido */}
      <Box sx={{ position: 'relative', zIndex: 2 }}>
        {/* Imagen de encabezado a todo ancho */}
        <Box
          sx={{
            mb: 8,
            width: '100%',
            overflow: 'hidden'
          }}
        >
          <Box
            component="img"
            src="cluster-background.png" 
            alt="Imagen del Clúster Raspberry Pi"
            sx={{
              width: '100%',
              height: 300,
              objectFit: 'cover',
              boxShadow: '0 20px 40px rgba(0,0,0,0.3)',
            }}
          />
        </Box>

        {/* Container principal para el contenido */}
        <Container maxWidth="lg" sx={{ pt: 0, pb: 8 }}>
          {/* Hero Section */}
          <Box sx={{ 
            textAlign: 'center', 
            mb: 8,
            color: 'white'
          }}>

          </Box>

          {/* Content Grid */}
          <Grid container spacing={6}>
            {/* Main Content */}
            <Grid item xs={12} md={8}>
              <Paper 
                elevation={0}
                sx={{ 
                  p: 4, 
                  mb: 4,
                  background: 'rgba(255,255,255,0.98)',
                  backdropFilter: 'blur(15px)',
                  borderRadius: 3,
                  border: '1px solid rgba(255,255,255,0.3)',
                  boxShadow: '0 8px 32px rgba(0,0,0,0.1)'
                }}
              >
                <Typography 
                  variant="h4" 
                  sx={{ 
                    fontWeight: 300,
                    mb: 3,
                    color: '#2c3e50'
                  }}
                >
                  ¿Qué es un Clúster de Raspberry Pi?
                </Typography>
                <Typography 
                  variant="body1" 
                  sx={{ 
                    lineHeight: 1.8,
                    color: '#34495e',
                    mb: 4
                  }}
                >
                  Un Clúster de Raspberry Pi es un conjunto de computadoras Raspberry Pi 
                  conectadas entre sí que trabajan de manera coordinada para ejecutar 
                  aplicaciones distribuidas. Cada Raspberry Pi actúa como un nodo en el 
                  Clúster, proporcionando recursos de CPU, memoria y almacenamiento.
                </Typography>

                <Typography 
                  variant="h4" 
                  sx={{ 
                    fontWeight: 300,
                    mb: 3,
                    color: '#2c3e50'
                  }}
                >
                  Kubernetes en Raspberry Pi
                </Typography>
                <Typography 
                  variant="body1" 
                  sx={{ 
                    lineHeight: 1.8,
                    color: '#34495e'
                }}
                >
                  Kubernetes es una plataforma de orquestación de contenedores que nos 
                  permite gestionar y escalar aplicaciones de manera automática. En nuestro 
                  Clúster de Raspberry Pi, Kubernetes coordina la ejecución de contenedores 
                  Docker a través de múltiples nodos, proporcionando alta disponibilidad 
                  y balanceamiento de carga.
                </Typography>
              </Paper>
            </Grid>

            {/* Benefits Sidebar */}
            <Grid item xs={12} md={4}>
              <Paper 
                elevation={0}
                sx={{ 
                  p: 4,
                  background: 'rgba(255,255,255,0.98)',
                  backdropFilter: 'blur(15px)',
                  borderRadius: 3,
                  border: '1px solid rgba(255,255,255,0.3)',
                  boxShadow: '0 8px 32px rgba(0,0,0,0.1)'
                }}
              >
                <Typography 
                  variant="h5" 
                  sx={{ 
                    fontWeight: 300,
                    mb: 3,
                    color: '#2c3e50'
                  }}
                >
                  Beneficios del Clúster
                </Typography>
                <List sx={{ p: 0 }}>
                  {[
                    { icon: <Speed />, title: "Alto Rendimiento", subtitle: "Procesamiento distribuido" },
                    { icon: <Security />, title: "Alta Disponibilidad", subtitle: "Tolerancia a fallos" },
                    { icon: <CloudQueue />, title: "Escalabilidad", subtitle: "Fácil adición de nodos" },
                    { icon: <Computer />, title: "Costo Efectivo", subtitle: "Hardware económico" }
                  ].map((item, index) => (
                    <ListItem key={index} sx={{ px: 0, py: 2 }}>
                      <ListItemIcon>
                        <Box
                          sx={{
                            background: `linear-gradient(135deg, ${theme?.palette?.primary?.main || '#2D5A8C'} 0%, ${theme?.palette?.primary?.dark || '#1C3C64'} 100%)`,
                            borderRadius: '50%',
                            p: 1,
                            color: 'white'
                          }}
                        >
                          {item.icon}
                        </Box>
                      </ListItemIcon>
                      <ListItemText 
                        primary={
                          <Typography sx={{ fontWeight: 500, color: '#2c3e50' }}>
                            {item.title}
                          </Typography>
                        }
                        secondary={
                          <Typography sx={{ color: '#7f8c8d', fontSize: '0.875rem' }}>
                            {item.subtitle}
                          </Typography>
                        }
                      />
                    </ListItem>
                  ))}
                </List>
              </Paper>
            </Grid>
          </Grid>

          {/* Use Cases Section */}
          <Paper 
            elevation={0}
            sx={{ 
              p: 4, 
              mt: 6,
              background: 'rgba(255,255,255,0.98)',
              backdropFilter: 'blur(15px)',
              borderRadius: 3,
              border: '1px solid rgba(255,255,255,0.3)',
              boxShadow: '0 8px 32px rgba(0,0,0,0.1)'
            }}
          >
            <Typography 
              variant="h4" 
              sx={{ 
                fontWeight: 300,
                mb: 4,
                textAlign: 'center',
                color: '#2c3e50'
              }}
            >
              Casos de Uso
